-- #482: publish terms 2026-10-29.1 (revision terms-2): Vinnot sells event tickets through Mercado Pago and keeps a commission.
-- Material change, so a new acceptance revision: earlier acceptors get the notice period (app.legal.notice-period) and the
-- TERMS_UPDATED email. V21 stays untouched (legal documents are immutable). Only the transactions section changes;
-- content_hash = sha256 of compact UTF-8 JSON {title, summary, sections[{id, title, body}]}, as documented in UC-LEG-08.
-- Guarded so a database that already holds this release is left as it is.
INSERT INTO legal_documents(document_type,version,acceptance_revision,locale,content_hash,title,summary,sections) VALUES ('terms','2026-10-29.1','terms-2','es','fb41052071766c2e1cf32fb02744c9d2ea34ab67b51a144bb9036b03293b9bfe','Términos de uso','El alcance del servicio y las reglas para utilizar Vinnot.','[{"id":"service","title":"Qué ofrece Vinnot","body":"Vinnot es una plataforma de descubrimiento y gestión de vinos, reseñas, cava personal, bodegas, eventos y rutas. El titular identificado en el centro legal opera la plataforma. Estos términos describen el uso de sus funciones; las condiciones específicas de cada evento deben consultarse antes de inscribirse."},{"id":"account","title":"Tu cuenta y su seguridad","body":"Utilizá datos de contacto propios y mantenelos actualizados. Protegé tus credenciales y no uses cuentas ajenas ni suplantes a otras personas. Los permisos de administración, moderación y organización se limitan a las acciones autorizadas para cada rol. Si sospechás un acceso no autorizado, cambiá la contraseña y contactanos."},{"id":"responsible","title":"Uso responsable","body":"Las funciones vinculadas con bebidas alcohólicas no deben utilizarse para promover su consumo por menores ni para eludir controles de edad de un organizador o establecimiento. Respetá las restricciones aplicables en tu lugar de residencia y en cada actividad. Vinnot no es un servicio médico ni una recomendación para consumir alcohol."},{"id":"content","title":"Contenido y aportes","body":"Conservás los derechos que te correspondan sobre tus aportes. Al enviar una reseña, foto o propuesta, autorizás el uso necesario para alojarla, mostrarla y revisarla dentro del servicio. No publiques material sobre el que no tengas derechos, datos privados de terceros o contenido engañoso. Las normas de comunidad y moderación explican los criterios aplicables."},{"id":"information","title":"Catálogo, escaneo e inteligencia artificial","body":"La información puede estar incompleta o desactualizada. Revisá la etiqueta y la ficha del productor para datos como alcohol, alérgenos, origen y composición. Un resultado de escaneo requiere verificar nombre, línea y variedad. El contenido generado con IA puede contener inferencias y errores; no constituye una certificación, diagnóstico ni garantía sobre una botella."},{"id":"transactions","title":"Eventos, entradas y pagos","body":"Vinnot permite que los organizadores vendan entradas para sus eventos. El pago lo procesa Mercado Pago según sus propios términos y condiciones; Vinnot no almacena datos de tarjetas. Vinnot retiene una comisión sobre el total de cada compra de entradas, que el organizador ve en su cuenta antes de empezar a vender. La tasa vigente figura en la sección Cobros de eventos de la cuenta de organizador; si cambia, se avisa con anticipación y el cambio se aplica solo a las ventas nuevas. Cada organizador es responsable de su evento, de las condiciones de devolución y de las cancelaciones. Las devoluciones se procesan a través de Mercado Pago. Si un organizador cobra por otro medio, como transferencia o pago en el lugar, gestiona ese cobro directamente y Vinnot no lo procesa ni cobra comisión. Consultá precio, disponibilidad, requisitos y condiciones de cancelación antes de comprar. Actualmente Vinnot no vende botellas ni ofrece suscripciones pagas."},{"id":"restrictions","title":"Restricciones y revisión","body":"No intentes acceder sin autorización, automatizar abuso, manipular puntuaciones ni interferir con el servicio. Ante incumplimientos pueden revisarse contenidos o restringirse accesos conforme a la política de moderación. Podés solicitar revisión por Contacto identificando la decisión. Una restricción no elimina los derechos que te reconozca la legislación aplicable."},{"id":"changes","title":"Cambios, baja y consultas","body":"Podés gestionar la baja de tu cuenta desde las opciones disponibles en el perfil o consultar por Contacto. Las modificaciones del servicio o de estos términos se identificarán mediante una versión actualizada; no se atribuye una aceptación retroactiva a usuarios existentes. Ninguna disposición pretende excluir derechos irrenunciables ni las responsabilidades que legalmente correspondan."}]'::jsonb) ON CONFLICT (document_type,version,locale) DO NOTHING;
INSERT INTO legal_documents(document_type,version,acceptance_revision,locale,content_hash,title,summary,sections) VALUES ('terms','2026-10-29.1','terms-2','en','0ecfaa1b0b53184367b9940810ff8e12256d608214ceef9e2227f1f3a367a30b','Terms of use','The scope of the service and the rules for using Vinnot.','[{"id":"service","title":"What Vinnot offers","body":"Vinnot is a platform for wine discovery and management, reviews, personal cellars, wineries, events and routes. The operator identified in the legal centre runs the platform. These terms describe the use of its features; the conditions of each event should be checked before registering."},{"id":"account","title":"Your account and its security","body":"Use your own contact details and keep them up to date. Protect your credentials and do not use other people''s accounts or impersonate others. Administration, moderation and organiser permissions are limited to the actions authorised for each role. If you suspect unauthorised access, change your password and contact us."},{"id":"responsible","title":"Responsible use","body":"Features relating to alcoholic beverages must not be used to promote consumption by minors or bypass an organiser''s or establishment''s age controls. Follow restrictions applicable where you live and at each activity. Vinnot is not a medical service or a recommendation to consume alcohol."},{"id":"content","title":"Content and contributions","body":"You retain the rights you hold in your contributions. When you submit a review, photo or proposal, you authorise the use necessary to host, display and review it within the service. Do not publish material you have no right to use, private information about others or misleading content. The community and moderation policies explain the applicable criteria."},{"id":"information","title":"Catalogue, scanning and artificial intelligence","body":"Information may be incomplete or outdated. Check the label and producer''s technical sheet for details such as alcohol, allergens, origin and composition. A scan result requires checking the name, product line and variety. AI-generated content may contain inferences and errors; it is not certification, a diagnosis or a guarantee about a bottle."},{"id":"transactions","title":"Events, tickets and payments","body":"Vinnot lets organisers sell tickets for their events. Payments are processed by Mercado Pago under its own terms and conditions; Vinnot does not store card details. Vinnot keeps a commission on the total of each ticket purchase, which the organiser sees in their account before they start selling. The current rate is shown in the Event payments section of the organiser account; if it changes, the change is announced in advance and applies only to new sales. Each organiser is responsible for their event, its refund conditions and cancellations. Refunds are processed through Mercado Pago. When an organiser collects payment another way, such as a bank transfer or payment at the venue, they handle it directly and Vinnot neither processes it nor charges a commission. Check price, availability, requirements and cancellation conditions before buying. Vinnot currently does not sell bottles or offer paid subscriptions."},{"id":"restrictions","title":"Restrictions and review","body":"Do not attempt unauthorised access, automate abuse, manipulate ratings or interfere with the service. Breaches may result in content review or access restrictions under the moderation policy. You can request review through Contact by identifying the decision. A restriction does not remove rights granted by applicable law."},{"id":"changes","title":"Changes, account closure and questions","body":"You can manage account closure through the available profile options or ask through Contact. Changes to the service or these terms will be identified through an updated version; no retroactive acceptance is attributed to existing users. No provision is intended to exclude mandatory rights or responsibilities imposed by law."}]'::jsonb) ON CONFLICT (document_type,version,locale) DO NOTHING;
